INSERT INTO `ws_product_description` VALUES (1,1,'Bits Quadrado Winner Steel 50% - 1/4\" x 4\"','<p>Bits Quadrado HSS 1/4 x 4</p>\n<p>Características:<br>\nMarca: Winner Steel<br>\nProduto: Bits Quadrado<br>\nMedida: 1/4 x 4<br>\nQuantidade: 1 unidade<br>\nDescrição: Fabricado com aço importado com Cobalto, proporcionando maior resistência a altas temperaturas e ao desgaste sem perder o corte;<br>\nNorma: DIN4964;</p>\n<p>-------------------------------------------</p>\n<p>- Fotos reais dos produtos</p>\n<p>- Atendimento Com Qualidade - Vários Canais de Atendimento</p>\n<p>- Devolução Gratuita - Isso mesmo, Sem custos!</p>\n<p>- Frete Seguro Para Todo Brasil</p>\n<p>- Frete Grátis para mais de uma peça adquirida</p>\n<p>- Produtos Com Garantia - Proteção para você e sua compra</p>\n<p>- Produtos a pronta entrega</p>\n<p>- Garantimos a devolução por arrependimento em até 7 dias após o recebimento e garantia de 90 dias contra defeitos de fabricação</p>','Bits Quadrado','Bits Quadrado Winner Steel 50% - 1/4\" x 4\"','Bits Quadrado fabricado com aço HSS (High Speed Steel). DIN 4964.','Bits Quadrado'),(1,2,'Bits Quadrado Winner Steel 50% - 1/4\" x 4\"','<p>Bits Quadrado HSS 1/4 x 4</p>\n<p>Características:<br>\nMarca: Winner Steel<br>\nProduto: Bits Quadrado<br>\nMedida: 1/4 x 4<br>\nQuantidade: 1 unidade<br>\nDescrição: Fabricado com aço importado com Cobalto, proporcionando maior resistência a altas temperaturas e ao desgaste sem perder o corte;<br>\nNorma: DIN4964;</p>\n<p>-------------------------------------------</p>\n<p>- Fotos reais dos produtos</p>\n<p>- Atendimento Com Qualidade - Vários Canais de Atendimento</p>\n<p>- Devolução Gratuita - Isso mesmo, Sem custos!</p>\n<p>- Frete Seguro Para Todo Brasil</p>\n<p>- Frete Grátis para mais de uma peça adquirida</p>\n<p>- Produtos Com Garantia - Proteção para você e sua compra</p>\n<p>- Produtos a pronta entrega</p>\n<p>- Garantimos a devolução por arrependimento em até 7 dias após o recebimento e garantia de 90 dias